Script.ScriptCode:
function captime(code)   //Pass precode from hidtime variable for which the duration needs to be calculated
{

var arrTime = f("hidCheckPart").domainLabels();
arrTime.unshift(' ');
//var mynm = String();
 // mynm = ""+arrTime[code];
//Response.Write(Cookies);

var myTime=Request.Form.item('myTime')
//Response.Write("time_t1="+myTime);
if(myTime!=null){
var t1 = parseInt(Request.Form.item('myTime'));
}

if(!f("hidtime").item(code).toBoolean())
{
  var sum =parseInt(0);
}
else {
  var sum = parseInt(f("hidtime").item(code).get());
}
if (t1==null) t1=0
var final = parseInt(sum+t1);
f('hidtime').item(code).set(final);

  //Response.Write("Second : "+final+"<br>");
var min = parseInt(final/60);  

var mod = parseInt(final%60);
 //Response.Write("mod : "+mod +"<br>");
if(mod < 10)
{
var finaldata = min+".0"+mod;
}
else
{
var finaldata = min+"."+mod;
}
 //Response.Write("LOI : "+finaldata +"<br>");
  f("Finaltime").item(code).set(finaldata);

}

function captimeCheck()
{
	var arr = f("hidCheckPart").domainValues();
//	var s = Request.QueryString.item("myTime");
// 	var s = Request.ServerVariables("mytime");
	var s = Request.Form.item('myTime')

	f("TestTime").set("Time: "+s);
	for(var i=0; i<arr.length; i++)
	{
		if(f("hidCheckPart").isect(set(arr[i])).size()>0)
		{
			captime(arr[i]);
		}
	}
}

