function DK(){
    if (!f(CurrentForm()).toBoolean()) {
        if (!f('DKShow').toBoolean()) {
            f('DKShow').set('1');
            RaiseError();
            SetQuestionErrorMessage(CurrentLang(), "You have not provided a response. Is that because you’re not sure or you would prefer not to answer?");
        }
    }
}
function qGridDK(aSet) {
    var list = set();
    for (var i = 0; i < aSet.length; i++) {
        if (aSet[i] != '98' && aSet[i] != '99') {
            list.add(aSet[i]);
        }
    }
    return list;
}
function DK_GRID()
{
    ClearForm(f('hideDKREF_flag_grid'))
    var qid = CurrentForm();
    var rows = f(qid).domainValues();
    var notAnswered = false;
    var skipCode = "97";

    for (var i = 0; i < rows.length && !notAnswered;i++) {
        var currRow = rows[i];
        if ((!f(qid).item(currRow).toBoolean() || f(qid).item(currRow).any(skipCode)) ) 
        {
            notAnswered = true;
        }
        else
        {
            //var resp2 = f(qid).item(currRow).get();
          //  var mod_qid = qid.replace('v1', '');
           // f(mod_qid).item(currRow).set(resp2);
        }}
    if (notAnswered)
    {
   // f(CurrentForm()+"_em").set("1"); 
    //errormessage('6');
    f('hideDKREF_flag_grid').set('1'); 
    RaiseError();
    SetQuestionErrorMessage(CurrentLang(), "You have not provided a response. Is that because you’re not sure or you would prefer not to answer?");
    }
}

