Multi.StartupScript:
var others = document.querySelectorAll(".cf-checkbox-answer__other.cf-text-box, .cf-text-box.cf-radio-answer__other, .cf-grid-3d-desktop__answer-other-input.cf-text-box, .cf-text-box, .cf-desktop-grid__answer-other");
for (let i = 0; i < others.length; i++) {
    var other = others[i];
    var parent = other.parentNode
    var text = other.placeholder + " <font color='#0000FF'><i>(Please specify)</i></font> ";
    other.placeholder = "";
    var newElement = document.createElement("span");
    newElement.innerHTML = text;
    parent.insertBefore(newElement, other);
}

Script.ScriptCode:
function maskB1() { 
    var s = set('b','a','f','h','p','i','j','u','v','l','m','k','o'); 

    //add() only allows 1 item, union() can handle multiple items
    if(f('QILTJOB').any('1','2')) { 
        /*s.add('c'); 
        s.add('s'); 
        s.add('d'); 
        s.add('e');         
        s.add('g'); */
        s=s.union(set('c','s','d','e','g'))
    } 
    //only show in SES
    if(f('QILTJOB').any('1')) { 
        /*s.add('q'); 
        s.add('r'); */
        s=s.union(set('q','r'))
    }     
    //only sohw in GOS-L
    if(f('QILTJOB').any('3')) { 
        s.add('t'); 
    }   
    if(f('QILTJOB').any('2','3')) { 
        s.add('n'); 
    }          
    return s; 
}

