if (f('HDEV').item('2').toBoolean()) {
  if (!IsEmail(f('HDEV').item('2'))) {
    errormessage('3');
  }
  else {
    f('HDEV').item('2').set(f('HDEV').item('2').get().trim())
    f('EmailCollected').set(f('HDEV').item('2').get())

    const MaxTryCount = 1

    //Request the tempory key
    var APIKey = "redacted"
    //Request the tempory key
    var requestString = "https://api.everest.validity.com/api/2.0/validation/addresses/";
    requestString = requestString + f('HDEV').item('2')
    if (f('HDEV').item('2').toBoolean()) {
      var response = Http.Get(requestString, "", { "X-API-Key": APIKey });
      var jsonObj = JSON.parse(response);
      var resultReturn = JSON.parse(JSON.stringify(jsonObj["results"]))
      var resultCategory = JSON.stringify(resultReturn["category"])
      f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""))
      f('EmailReturnText').set(JSON.stringify(resultReturn))

      var returnvalueCat = f('EmailReturnValues_category').get()


      if (returnvalueCat.includes("email_domain_invalid")) {
        //if no traslation, can use below
        //customErrorMsg_ENG("Domain for email (AFTER '@') does not exist, please double check it")

        //otherwise make sure using the correct code defnied in standarderrormessage
        errormessage(14)
      }
      else if (returnvalueCat.includes("email_address_invalid")) {
        errormessage(15)

      }
      else if (returnvalueCat.includes("email_account_invalid")) {

        errormessage(16)
      }
      else if (returnvalueCat.includes("accept_all", "role_address", "disposable") && Number(f('EmailTryCount') || 0) < MaxTryCount) {

        f('EmailTryCount').set(Number(f('EmailTryCount') || 0) + 1)
        errormessage(17)


      }
    }
  }
}

Script.ScriptCode:
// Function to clear multi
// To use  call clearMulti("questionID") from whereever required

function clearMulti(qID) {

    var qans=f(qID).domainValues()

    for (var i=0;i<qans.length;i++)
    {
        var code=qans[i];
        f(qID).item(code).set(null)
    }
}

function CreateCategoriesFromGrid(qid, code){
    var s = set();
    var ques = f(qid)
    var list = ques.domainValues()
    for (var x = 0; x < list.length; x++) {
      if (ques.item(list[x]).any(code)) {
        s.add(list[x].toString())
      }
    }
    return s; // returns the correct set of codes for the mask.
}

function numberMaskLessThan(qid, code, qidTarget) { 
    //var list = a('C1a_stmt').members() 
    var list = a(qidTarget).members()
    var s = set(); 
    for (var x = 0; x < list.length; x++) { 
        if (f(qid + "_" + list[x]).toBoolean() && f(qid + "_" + list[x]).any(code)) { //checks scale and if the element has been answered at all 
            s.add(list[x].toString()); //returns only the codes that are answered and are greater than "code" 
        } 
    } 
    return s; // returns the correct set of codes for the mask. 
}

//To call the function, use square brackets ([]): numberMaskLessThan('C1a', ['1','2','3'], 'C1a_stmt')

function ScoreFilter(qID)
{
  var form = f(qID);
  var codes = form.domainValues();
  var s = set(); 
  for (var i=0; i<codes.length; i++)
  {
    var code = codes[i];
    if (form[code].get() == '1' || form[code].get() == '2')
    {
      s.add(code);
    }
  }
  return s;
}

